select.if:
SELECT distinct A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND (A.ACCT_NO = #{initValue, jdbcType=VARCHAR} OR (CONCAT(PORTFOLIO_ID,A.ACCT_NO)) = #{initValue, jdbcType=VARCHAR} )
AND TRADE_PLACE = #{tradeMarket, jdbcType=VARCHAR}

SELECT SEC_ACCT_ID hidCode, SEC_ACCT_ID code, SEC_ACCT_NAME name, SEC_ACCT_NAME shortName FROM STL_SEC_ACCT_INFO
( STL_SEC_ACCT_INFO.SEC_ACCT_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR STL_SEC_ACCT_INFO.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND STL_SEC_ACCT_INFO.SEC_ACCT_ID = #{initValue, jdbcType=VARCHAR}
